exercises.reference:
def is_leap(year):
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

def days_in_month(month, year):
    if month == 2:
        if is_leap(year):
            return 29
        return 28
    if month == 4 or month == 6 or month == 9 or month == 11:
        return 30
    return 31

def month_of_day(n, year):
    month = 1
    while n > days_in_month(month, year):
        n -= days_in_month(month, year)
        month += 1
    return month

print(month_of_day(60, 2024), month_of_day(60, 2026))
